method.description:
Creates an error result with the specified error message. Useful for custom validation errors.
[codeblock lang=gdscript]
# Validate player data from YAML
func validate_player_data(data):
    if !data.has("name"):
        return YAMLResult.error("Player data missing 'name' field")

    if !data.has("level") or typeof(data.level) != TYPE_INT:
        return YAMLResult.error("Player requires integer 'level' field")

    if data.level < 1:
        return YAMLResult.error("Player level must be at least 1")

    # Return the validated data
    return data

# Use the validator
var result = YAML.parse(player_yaml)
if !result.has_error():
    var validate_result = validate_player_data(result.get_data())
    if validate_result.has_error():
        print("Validation error: " + validate_result.get_error_message())
[/codeblock]

Returns the result data. For multi-document YAML, specify [param index] to access a specific document. [codeblock lang=gdscript] var yaml_text = """ # Player stats name: Hero health: 100 --- # Game settings difficulty: hard enable_tutorial: false """
var result = YAML.parse(yaml_text) if !result.has_error(): var player_data = result.get_data(0) var settings = result.get_data(1)
print("Player: %s (Health: %d)" % [player_data.name, player_data.health]) print("Difficulty: %s" % settings.difficulty) [/codeblock]

Alias for [method get_data] for clarity when working with multiple documents.
[codeblock lang=gdscript]
var result = YAML.parse(multi_doc_yaml)

if !result.has_error():
    var doc_count = result.get_document_count()
    print("Found %d documents" % doc_count)

    # Process each document
    for i in range(doc_count):
        var doc = result.get_document(i)
        process_document(doc)
[/codeblock]

Returns the number of documents in the result. Returns [code]0[/code] for error results.
[codeblock lang=gdscript]
var result = YAML.parse(yaml_text)

if !result.has_error():
    var count = result.get_document_count()
    if count > 1:
        print("This is a multi-document YAML with %d documents" % count)
    else:
        print("This is a single-document YAML")
[/codeblock]

Returns the column number where the error occurred. Returns [code]-1[/code] if not applicable.
[codeblock lang=gdscript]
var result = YAML.parse(yaml_text)

if result.has_error():
    var line = result.get_error_line()
    var column = result.get_error_column()

    if line > 0 and column > 0:
        # Highlight the error position
        var yaml_lines = yaml_text.split("\n")
        var error_line = yaml_lines[line - 1]

        print(error_line)
        print(" ".repeat(column - 1) + "^ Error here")
[/codeblock]

Returns the line number where the error occurred. Returns [code]-1[/code] if not applicable.
[codeblock lang=gdscript]
var result = YAML.parse(yaml_text)

if result.has_error():
    var error_line = result.get_error_line()

    if error_line > 0:
        print("Error at line %d" % error_line)

        # You might load the file in an editor and scroll to this line
        editor.goto_line(error_line)
[/codeblock]

Returns the raw error message without line and column information. [codeblock lang=gdscript] var result = YAML.parse(yaml_text)
if result.has_error(): var message = result.get_error_message()
# Log the basic error type match message: "unexpected end of file": push_error("YAML file is incomplete") "mapping values are not allowed in this context": push_error("YAML has incorrect indentation") _: push_error("YAML error: " + message) [/codeblock]

Returns the style information if any. Only available if style detection was enabled during parsing.
[codeblock lang=gdscript]
# Parse with style detection
var result = YAML.parse(yaml_text, null, true)

if !result.has_error() and result.has_style():
    var data = result.get_data()
    var style = result.get_style()

    # Modify the data but preserve formatting
    data.player.health = 200

    # Reserialize with the same style
    var output = YAML.stringify(data, style)
    save_file("user://modified_config.yaml", output.get_data())
[/codeblock]

Returns [code]true[/code] if the result contains an error, [code]false[/code] otherwise.
[codeblock lang=gdscript]
var result = YAML.parse(config_text)

if result.has_error():
    # Error handling
    print("Failed to parse configuration: " + result.get_error())
    print("Using default configuration instead")
    return default_config
else:
    # Success - use the parsed data
    return result.get_data()
[/codeblock]

Returns [code]true[/code] if the result contains style information, [code]false[/code] otherwise.
[codeblock lang=gdscript]
var result = YAML.load_file("res://data/game_config.yaml", null, true)

if !result.has_error():
    if result.has_style():
        print("Style information was successfully detected")

        # Extract and modify the style
        var style = result.get_style()
        var nested_style = style.get_at_path("player/inventory", true)
        nested_style.set_flow_style(YAMLStyle.FLOW_SINGLE)
    else:
        print("No style information detected")
[/codeblock]
